import collections,datetime,json,pathlib
ROOT=pathlib.Path(__file__).resolve().parent
read=lambda name:json.loads((ROOT/name).read_text())
rows=read('sources.json');sync=read('sync.json');summary=read('summary.json');pairs=read('pairs-to-judge.json');smoke=read('smoke.json')
byid={s['id']:s for s in sync['sources']};new_ids={r[0] for r in rows};total=sum(byid[s]['items'] for s in new_ids)
